-- On-call ladder pages + estimates (see functions oncall, estimates). Cron: donna-oncall-sweep (*/5), donna-estimates-sweep (0 */6).
create table if not exists public.pages (id uuid primary key default gen_random_uuid(), account_id uuid not null references accounts(id) on delete cascade, job_id uuid references jobs(id) on delete cascade, step int not null default 0, to_phone text not null, to_user_id uuid, message text not null, sent_at timestamptz not null default now(), acked_at timestamptz, acked_by uuid, escalated_at timestamptz, created_at timestamptz not null default now());
create table if not exists public.estimates (id uuid primary key default gen_random_uuid(), account_id uuid not null references accounts(id) on delete cascade, job_id uuid references jobs(id) on delete set null, contact_id uuid, number text not null, status text not null default 'draft', lines jsonb not null default '[]'::jsonb, total_cents int not null default 0, notes text, customer_name text, customer_phone text, customer_email text, service_address text, approve_token text not null default encode(gen_random_bytes(12),'hex'), valid_days int not null default 30, sent_at timestamptz, approved_at timestamptz, declined_at timestamptz, expires_at timestamptz, approved_via text, decline_reason text, converted_job_id uuid, converted_appointment_id uuid, nudged_at timestamptz, created_by uuid, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
-- RPCs: next_estimate_number(uuid), estimate_public(text) (anon). Storage bucket: job-photos (private).
